"""Resume SEAL ONLY from existing tested bytes after host restart.
No math/test/shadow/physics rerun, original input trace reads, or Git operation.
"""
from pathlib import Path
import datetime,hashlib,json,re
R=Path(__file__).resolve().parent

def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def new(p,obj):
    assert not p.exists(),str(p)+' already exists; no replacement'
    p.write_text(json.dumps(obj,ensure_ascii=False,indent=2,allow_nan=False)+'\n',encoding='utf-8')
def meta(p):return {'path':str(p),'relative':p.relative_to(R).as_posix(),'bytes':p.stat().st_size,'SHA':sha(p)}
def main():
    assert not (R/'INDEX.json').exists(),'Sealed stage must not be replayed'
    result_path=R/'attempts/001/RESULT.json';summary_path=R/'attempts/001/shadow/SUMMARY.json'
    result=json.loads(result_path.read_text(encoding='utf-8'));summary=json.loads(summary_path.read_text(encoding='utf-8'))
    assert result['all_passed'] and result['units']=={'tests':15,'failures':0,'errors':0,'passed':True}
    assert result['shadow']['completed'] and summary['projection_rows']==4400
    for e in result['source_files']:
        assert sha(R/e['name'])==e['SHA'],'current source differs from executed attempt001: '+e['name']
        assert sha(R/'attempts/001/sources'/e['name'])==e['SHA'],'saved executed source bytes differ'
    for path,h in result['protected_hashes'].items():assert sha(Path(path))==h,'prior protected source changed: '+path
    outputs=[]
    for e in summary['derived_artifacts']:
        p=Path(e['path']);assert p.is_relative_to(R/'attempts/001/shadow')
        assert p.stat().st_size==e['bytes'] and sha(p)==e['SHA'],'new derived output integrity mismatch'
        outputs.append({**meta(p),'producer_SHA_verified_from_existing_derived_output':True,'not_original_raw_trace':True})
    rows=[];totals={str(T):{'numeric_windows':0,'trusted_windows':0,'conditional_interval_nonfreefall_only':0} for T in (50000,100000,150000)}
    for c in summary['cases']:
        for k,w in c['windows'].items():
            assert w['strict_trusted_windows']==0 and w['conditional_trusted_windows']==0 and w['all_returned_cues_uncertain']
            rows.append({'case':c['case'],'T_ms':w['T_ms'],'rows_total':w['rows_total'],'numeric_windows':w['numeric_conditional_windows'],'numeric_rate':w['numeric_rate'],'radius_p50_m_s2':w['proposed_radius_m_s2']['p50'],'radius_p95_m_s2':w['proposed_radius_m_s2']['p95'],'nominal_window_age_ms':w['window_average_age_us']['p50']/1000,'boundary_term_p50_m_s2':w['boundary_term_m_s2']['p50'],'transport_term_p50_m_s2':w['missing_transport_term_m_s2']['p50'],'conditional_interval_nonfreefall_only':w['conditional_interval_nonfreefall_diagnostic_only'],'trusted_cues':0,'hardware_binding':False})
            totals[k]['numeric_windows']+=w['numeric_conditional_windows'];totals[k]['conditional_interval_nonfreefall_only']+=w['conditional_interval_nonfreefall_diagnostic_only']
    new(R/'CASE_WINDOW_TABLE.json',{'rows':rows,'totals_by_T_us':totals,'overlapping_windows_are_not_independent_trials':True,'not_truth_accuracy_or_contact_qualification':True})
    new(R/'DERIVED_OUTPUT_MANIFEST.json',{'outputs':outputs,'source_manifest_SHA':summary['projection_manifest_SHA'],'projection_input_metadata_only':summary['input_projection_provenance'],'no_original_trace_rehash_or_read':True})
    new(R/'SEAL_INTERRUPTION_RECEIPT.json',{'event':'host_restart_before_stage_seal','previous_status':'attempt001 synthetic15/15 and shadow4400 completed; documentation in progress; NO INDEX existed, not previously sealed','recovery':'Use on-disk attempt001, all executed source bytes/SHA and protected dependencySHA verified; no synthetic/shadow/physics rerun','new_reader_or_model_failures':0,'sealed_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat()})
    new(R/'SOURCE_MANIFEST.json',{'executed_attempt':'attempts/001','executed_source_files':result['source_files'],'proof_budget_was_frozen_before_execution':result['proof_budget_frozen_before_synthetic_execution'],'protected_prior_source_SHA_verified_at_seal':result['protected_hashes'],'math_core':meta(R/'window_math.py'),'shadow_core':meta(R/'shadow_windows.py'),'no_new_alpha_qdd_estimation_inputs':True})
    new(R/'ASSUMPTIONS.json',{'conditional_envelopes':summary['assumptions'],'frozen_cue_configuration':summary['frozen_cue_configuration'],'strict_transport_correlation_unbound':True,'conditional_model_only_not_actual_capture_exactness':True,'gyro_proper_intrawindow_correlation_not_observed':True,'fixed_error_correlation_not_replaced_by_independence_or_automatic_cancellation':True,'noise_not_reduced_by_mean_or_window_sample_count':True,'hardware_binding':False,'conditional_confidence_cap':.50,'returned_cues_all_uncertain':True})
    new(R/'VALIDATION.json',{'status':'SEALED_FINITE_COM_WINDOW_IDENTITY_AND_CONDITIONAL_SHADOW_NOT_HARDWARE_CUE_QUALIFIED','units':result['units'],'projection_rows':4400,'window_T_ms':[50,100,150],'totals_by_T_us':totals,'all_trusted_cues':0,'source_bytes_match_executed_attempt':True,'old_protected_source_SHA_unchanged':result['protected_hashes'],'existing_derived_output_producerSHA_verified':True,'resumed_after_restart_without_test_or_physics_rerun':True,'alpha_qdd_differenced_by_estimator':False,'new_physics_steps':0,'original_trace_DR_GT_reads':0,'Git_newagent_realIO':False,'PH3pending':True})
    new(R/'PH3_PREPARATION_HANDOFF.json',{'status':'WAIT_PARENT_WRITTEN_SOURCE_CUTOFF_BEFORE_CAPTURE','integrated_stage_to_be_sealed_now':True,'future_scope_requested':'through parent R34 and sealed C3/HOST/H2/DYNAMIC_COM/CAPTURE_AUDIT/INTEGRATED_WINDOW','explicit_future_exclusions':['active ASQP_V3','FRONT_RANGE_PROPOSAL_V1 still active','heading_hold_controller_v1 new unrun','R35+','temporary active scripts'],'future_owner_worktree':'F:/RMPOLAR-RL/repo-lqr-robust','future_owner_branch':'mod4v1-lqr-mpc-robust','future_base':'02b5ff84b905a4e40f207a44b0491aeff2f79b7e','no_source_snapshot_or_Git_operation_done_in_this_seal':True,'phase1_phase2_not_replayed':True,'next_action_requires_parent_written_scope_cutoff':True})
    table='\n'.join(f"|{x['case']}|{int(x['T_ms'])}|{x['numeric_windows']}|{x['radius_p50_m_s2']:.6f}|{x['radius_p95_m_s2']:.6f}|{x['nominal_window_age_ms']:.2f}|0|" for x in rows)
    readme='''# Integrated COM Window v1 — finite-window identity, conditional shadow\n\n**现已封存：磁盘attempt001的15/15synthetic与4400projection-shadow均完成，执行源码/原source snapshots/旧依赖SHA已核。宿主重启前仅中途状态、未有INDEX；本次仅补齐文档和seal，没有重跑测试/物理。全部可信cue仍UNKNOWN、hardwarebinding=false，PH3pending。**\n\n## 精确恒等式与用途\n\nIMU固定lever s，完整COM r(q)，BODY量`u=omega×(r−s)+rDot`：\n\n```text\nvCOM^W-vIMU^W = R u\nmean_window properCOM^W = integral_window(R fIMU_B)/T\n                         + (R_end u_end-R_start u_start)/T\n```\n\n它不加g、不求alpha/qdd测量；对Ru求导恰含alpha×rho、omega×omega×rho、2omega×rDot及rDDot，所以movingleg的Jqdd/convective项不曾被丢弃，只转换成速度边界。rDot来自public31body FK的J(q)qd。\n\n窗口首relativeR=I，仅gyro积分；未知world常旋转只左旋结果，不改变norm。每bin解析S(omega,h)=integral exp([omega]t)dt对其piecewise-constant模型精确，**不是对原boxcar真实transport精确**。详[公式/坐标/预算](<THEORY_AND_BUDGET.md>)与[mean信息缺失反例](<BOXCAR_INFORMATION_LIMIT.md>)。\n\n## 50/100/150ms结果\n\n数值窗口从contiguous mean epoch取N个完整bin及两个端点，boot/重复首包不赚新窗口。radius是显式smoothness/geometry/端点噪声假设下的局部工程scale，不是实际global error保证。\n\n|case|T ms|可算窗口|radius p50 m/s²|radius p95|平均量nominal age ms|可信cue|\n|---|---:|---:|---:|---:|---:|---:|\n'''+table+'''\n\n150ms下conditional interval排除zero并符合nonfreefall proposed区间的窗口数量是747/301/136/116，仅为**条件区间诊断**，不是接触身份、可靠contactcue或FSM资格；confidence cap仍.50低于冻结.60，所有返回cue保持UNKNOWN。50/100ms的该条件诊断数量均为0。\n\n端点误差/T确实随长窗缩小；例如stand的boundary p50约8.366/4.183/2.789m/s²。proper噪声项约.424785m/s²不随N缩小，gyro路径/transport误差随时间增长。更长窗口还增加T/2年龄，不是当前瞬时cue。DR队列观测10ms使25/50/75ms变成35/60/85ms；原20point leftsample firstmoment另比窗口中点早.25ms，已记录。重叠窗口不是独立物理试验。\n\n对旧point-COM sphere约12m/s²，长窗条件sphere较小是数学上有前景的方向，但temporal target/transport假设不同，**不等于当前point精度或真实benchmark成功率提升**。\n\n## 没有偷掉的误差与边界\n\n- PUBLIC D1同半宽用于全部case，不读或反推D0–D7receipt，不按nominal标签置0，更没有除sqrt20/窗口N。\n- q是endepoch，qd/gyro仍是前20sample均值；端点误差含5.25ms异时与声明rate-slope envelope，没冒成同步瞬时。\n- 20point boxcar未保留intrawindow R/proper相关项；conditional用预先写定alpha/qd/proper slope envelope作transport预算。没有用midpoint R乘mean proper叫作精确。\n- 固定BODY model bias传播矩阵`[R1[omega1]−[omega0]]/T`另列；默认triangle界不要求独立性、不自动抵消。\n- wheel phase未知按nominal非零径向MCI fullphase/速度缺项界，不假balanced；硬件MCI/零点/lever/滤波校准仍未绑定。\n- 这仅是窗口平均specific-force候选，不是全表面air/contact/guide身份、270mm/RM/board资格。\n\n## 已保存证据\n\n- [核心window math](<window_math.py>)、[shadow实现](<shadow_windows.py>)、[15单测源码](<test_window.py>)、[runner](<run_checks.py>)。\n- [首次RESULT和全部sourceSHA](<attempts/001/RESULT.json>)、[unit log](<attempts/001/unittest.log>)、[完整shadow summary](<attempts/001/shadow/SUMMARY.json>)。\n- [每case/window表](<CASE_WINDOW_TABLE.json>)、[逐窗口derived output/producerSHA](<DERIVED_OUTPUT_MANIFEST.json>)、[假设](<ASSUMPTIONS.json>)、[source manifest](<SOURCE_MANIFEST.json>)、[validation](<VALIDATION.json>)、[INDEX](<INDEX.json>)。\n- [重启中途恢复记录](<SEAL_INTERRUPTION_RECEIPT.json>)：从已落盘字节核对后seal，未把中途状态冒成已sealed。\n\n15项数学覆盖static、rigid spin freefall、movingleg/public31body、constant net force、坐标变换/norm、完整rDDot/Coriolis展开、解析SO3积分、fixed-bias传播、噪声不随N缩小及相关raw均值恒等式。fixture生成器可有解析导数用于造信号；估计器接口没有alpha/qdd/world yaw输入。\n\n## 2k最小提案与后续\n\n[2k提案](<MINIMUM_2K_CAPTURE_PROPOSAL.md>)仅提出字段/证明要求，未实现父publisher/新physics。same-window D1offset加到各raw使weightedmean代数一致，但同窗差分offset消去，属于**信息增强/相关噪声新branch**，不冒旧benchmark或IID20降噪。控制器只见noisyraw，不见clean/offset，整窗按D3延迟；endpoint q/qd同步仍需绑定。浮点逐bit一致与实数恒等式分开说明。\n\n[PH3准备交接](<PH3_PREPARATION_HANDOFF.json>)保持待父书面cutoff确认：当前seal不追active source、不snapshot/commit、不重record Phase1/2。全部0physics/Git/newagent/完整原trace/DR/GT；旧保护SHA不变，整体Goal继续active。\n'''
    (R/'README.md').write_text(readme,encoding='utf-8')
    files=sorted(p for p in R.rglob('*') if p.is_file() and '__pycache__' not in p.parts and p.name!='INDEX.json')
    new(R/'INDEX.json',{'module':'INTEGRATED_COM_WINDOW_V1','status':'SEALED_FORMULA_AND_CONDITIONAL_WINDOW_SHADOW_CUES_UNKNOWN','sealed_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'core':meta(R/'window_math.py'),'shadow':meta(R/'shadow_windows.py'),'README':meta(R/'README.md'),'validation':meta(R/'VALIDATION.json'),'attempt001_unchanged_and_not_rerun':True,'units':result['units'],'projection_rows':4400,'horizons_ms':[50,100,150],'all_trusted_cues':0,'hardware_binding':False,'original_trace_DR_GT_reads':0,'new_physics_Git_agents_realIO':False,'PH3pending':True,'protected_prior_SHA':result['protected_hashes'],'files':[meta(p) for p in files]})
    links=0
    for p in R.glob('*.md'):
        for dest in re.findall(r'\]\(<([^>]+)>\)',p.read_text(encoding='utf-8')):assert (p.parent/dest.split('#')[0]).exists(),(p,dest);links+=1
    print(json.dumps({'sealed':True,'core':meta(R/'window_math.py'),'shadow':meta(R/'shadow_windows.py'),'README':meta(R/'README.md'),'INDEX':meta(R/'INDEX.json'),'VALIDATION':meta(R/'VALIDATION.json'),'units':result['units'],'projection_rows':4400,'totals_by_T_us':totals,'protected_SHA_count':len(result['protected_hashes']),'links_checked':links,'no_rerun_or_physics_or_Git':True,'next_scope_cutoff_wait_parent_written_confirmation':True},ensure_ascii=False,indent=2))
if __name__=='__main__':main()
